- *   Copyright (C) 2007 David Sterba
- */
-
-#include <linux/kernel.h>
-#include <linux/module.h>
-#include <linux/mutex.h>
-#include <linux/ppp_defs.h>
-#include <linux/if.h>
-#include <linux/ppp-ioctl.h>
-#include <linux/sched.h>
